// ELEMENTS:
// 1. Navy liso com o filete vermelho no topo
// 2. Selo: círculo em traço fino que se desenha, com um visto branco e um anel exterior a pulsar uma vez
// 3. Frase (anim.text) em Light, palavras **marcadas** em Heavy
// 4. Pílulas vermelhas com texto branco (items) a entrar em sequência; sub em névoa
// 5. Grão de filme + vinheta
import React, { useId } from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, Easing } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY = "#001F44";
const RED = "#DE212B";
const WHITE = "#FFFFFF";
const MIST = "#C9D3E3";
const LINE = "rgba(255,255,255,0.45)";
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const Grain: React.FC<{ f: number }> = ({ f }) => {
  const id = useId().replace(/:/g, "");
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 45%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.28) 100%)" }} />
      <svg width="100%" height="100%" style={{ position: "absolute", inset: 0, opacity: 0.08, mixBlendMode: "overlay" }}>
        <filter id={id}>
          <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves={2} seed={f % 12} />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter={`url(#${id})`} />
      </svg>
    </AbsoluteFill>
  );
};

const SeloConfirmacao: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const u = format === "landscape" ? box.height / 1080 : format === "half" ? (box.height / 960) * 0.85 : W / 1080;
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const sub = String(p.sub ?? "").trim();
  const items = Array.isArray(p.items) ? (p.items as unknown[]).map((x) => String(x).trim()).filter(Boolean) : [];
  const parts = String(anim.text ?? "").split(/(\*\*[^*]+\*\*)/).filter(Boolean);

  const show = (delay: number, len = 0.7): number =>
    interpolate(f, [Math.round(delay * fps), Math.round((delay + len) * fps)], [0, 1], { ...clamp, easing: EASE });
  const rise = (delay: number): React.CSSProperties => {
    const t = show(delay);
    return { opacity: t, transform: `translateY(${(1 - t) * 26 * u}px)` };
  };
  const pulse = show(1.2, 1.0);

  return (
    <AbsoluteFill style={{ backgroundColor: NAVY, overflow: "hidden" }}>
      <AbsoluteFill style={{ alignItems: "center", justifyContent: "center", flexDirection: "column", textAlign: "center", padding: `0 ${90 * u}px`, gap: 56 * u }}>
        <svg width={360 * u} height={360 * u} viewBox="0 0 200 200" style={{ overflow: "visible" }}>
          <circle cx={100} cy={100} r={78 + pulse * 22} fill="none" stroke={WHITE} strokeWidth={1.5} opacity={(1 - pulse) * 0.6 * (pulse > 0 ? 1 : 0)} />
          <circle cx={100} cy={100} r={78} fill="none" stroke={LINE} strokeWidth={2.5} pathLength={1} strokeDasharray={1} strokeDashoffset={1 - show(0.1, 1.0)} transform="rotate(-90 100 100)" />
          <path d="M66 102 L90 126 L136 78" fill="none" stroke={WHITE} strokeWidth={6} strokeLinecap="round" strokeLinejoin="round" pathLength={1} strokeDasharray={1} strokeDashoffset={1 - show(0.8, 0.6)} />
        </svg>
        <div style={{ fontFamily: FONTS.display, fontSize: 104 * u, lineHeight: 1.08, color: WHITE, maxWidth: 900 * u, ...rise(0.9) }}>
          {parts.map((s, i) => <span key={i} style={{ fontWeight: s.startsWith("**") ? 800 : 300 }}>{s.replace(/\*\*/g, "")}</span>)}
        </div>
        {items.length ? (
          <div style={{ display: "flex", gap: 24 * u, flexWrap: "wrap", justifyContent: "center" }}>
            {items.map((x, i) => {
              const t = show(1.4 + i * 0.25, 0.5);
              return (
                <div key={i} style={{ background: RED, color: WHITE, borderRadius: 999, padding: `${16 * u}px ${38 * u}px`, fontFamily: FONTS.body, fontWeight: 600, fontSize: 32 * u, letterSpacing: "0.2em", textTransform: "uppercase", opacity: t, transform: `scale(${0.8 + 0.2 * t})` }}>{x}</div>
              );
            })}
          </div>
        ) : null}
        {sub ? <div style={{ fontFamily: FONTS.display, fontWeight: 300, fontSize: 48 * u, color: MIST, ...rise(1.9) }}>{sub}</div> : null}
      </AbsoluteFill>
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 6 * u, background: RED }} />
      <Grain f={f} />
    </AbsoluteFill>
  );
};

export default SeloConfirmacao;
